class LineDiffTest(unittest.TestCase):
    def test_ops(self):
        for a, b, expected in LINES:
            self.assertEqual(diff_lines(a, b), expected, (a, b))

    def test_unified(self):
        for a, b, context, expected in UNIFIED:
            self.assertEqual(unified_diff(a, b, "a", "b", context), expected, (a, b, context))

    def test_invalid_context(self):
        for context in (-1, True, 1.5):
            with self.assertRaises(ValueError):
                unified_diff("a\n", "b\n", context=context)

    def test_size_limit(self):
        big = "x\n" * 500_001
        with self.assertRaises(ValueError):
            diff_lines(big, big)

    def test_no_common_line(self):
        a = "".join(f"a{i}\n" for i in range(3000))
        b = "".join(f"b{i}\n" for i in range(3000))
        ops = [op for op, _ in diff_lines(a, b)]
        self.assertEqual(ops.count("-"), 3000)
        self.assertEqual(ops.count("+"), 3000)
        self.assertNotIn("=", ops)

    def test_large_input_is_fast(self):
        # Lines repeat, so every line also occurs in the other text and Myers does the real work.
        a_lines = [f"line {i % 997}" for i in range(100_000)]
        b_lines = list(a_lines)
        for k in range(20):
            b_lines[k * 4999 + 7] = f"line {(k * 4999 + 500) % 997}"
        a, b = "\n".join(a_lines) + "\n", "\n".join(b_lines) + "\n"
        started = time.monotonic()
        ops = diff_lines(a, b)
        self.assertLess(time.monotonic() - started, 10)
        removed = sum(op == "-" for op, _ in ops)
        self.assertEqual(removed, sum(op == "+" for op, _ in ops))
        self.assertTrue(0 < removed <= 20)
        self.assertEqual([line for op, line in ops if op != "+"], a_lines)
        self.assertEqual([line for op, line in ops if op != "-"], b_lines)


if __name__ == "__main__":
    unittest.main()
